def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        # Parse in chunks to avoid Python's limit on decimal string conversion.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue

            action = history.pop()
            kind = action[0]

            if kind == "open":
                account = action[1]
                del balances[account]
                frozen.discard(account)
            elif kind == "deposit":
                balances[action[1]] -= action[2]
            elif kind == "withdraw":
                balances[action[1]] += action[2]
            elif kind == "transfer":
                source, destination, amount = action[1:]
                balances[source] += amount
                balances[destination] -= amount
            elif kind == "freeze":
                frozen.remove(action[1])
            else:
                frozen.add(action[1])
            continue

        if verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account, amount_token = parts[1:]
            amount = parse_amount(amount_token)
            if amount is None:
                rejected.append(index)
                continue

            if verb == "open":
                if account in balances:
                    rejected.append(index)
                    continue
                balances[account] = amount
                history.append(("open", account))
            elif verb == "deposit":
                if account not in balances or amount == 0:
                    rejected.append(index)
                    continue
                balances[account] += amount
                history.append(("deposit", account, amount))
            else:
                if (
                    account not in balances
                    or account in frozen
                    or amount == 0
                    or balances[account] < amount
                ):
                    rejected.append(index)
                    continue
                balances[account] -= amount
                history.append(("withdraw", account, amount))
            continue

        if verb == "transfer" and len(parts) == 4:
            source, destination, amount_token = parts[1:]
            amount = parse_amount(amount_token)
            if (
                amount is None
                or amount == 0
                or source == destination
                or source not in balances
                or destination not in balances
                or source in frozen
                or balances[source] < amount
            ):
                rejected.append(index)
                continue
            balances[source] -= amount
            balances[destination] += amount
            history.append(("transfer", source, destination, amount))
            continue

        if verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account not in balances:
                rejected.append(index)
            elif verb == "freeze":
                if account in frozen:
                    rejected.append(index)
                else:
                    frozen.add(account)
                    history.append(("freeze", account))
            else:
                if account not in frozen:
                    rejected.append(index)
                else:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
            continue

        rejected.append(index)

    return balances, rejected
